namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

public static class RecipeStore
{
    private static readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough
San Marzano tomatoes
Fresh mozzarella
Fresh basil
Olive oil
Salt", Steps = "1. Preheat oven to 475°F
2. Roll out dough on floured surface
3. Spread crushed tomatoes evenly
4. Tear mozzarella and distribute
5. Bake 10-12 minutes until crust is golden
6. Top with fresh basil and drizzle olive oil", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken breast
Yogurt
Garam masala
Turmeric
Cumin
Tomato sauce
Heavy cream
Garlic
Ginger", Steps = "1. Marinate chicken in yogurt and spices for 2 hours
2. Grill or broil chicken until charred
3. Sauté garlic and ginger in oil
4. Add tomato sauce and spices, simmer 15 min
5. Add cream and cooked chicken
6. Simmer 10 more minutes, serve with rice", AverageRating = 4.8, RatingCount = 24 },
        new Recipe { Id = 3, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef
Taco seasoning
Corn tortillas
Lettuce
Tomato
Cheddar cheese
Sour cream
Salsa", Steps = "1. Brown ground beef in skillet
2. Add taco seasoning and water, simmer 5 min
3. Warm tortillas in dry pan
4. Assemble tacos with meat and toppings
5. Serve with salsa and sour cream", AverageRating = 4.2, RatingCount = 8 },
        new Recipe { Id = 4, Title = "Pad Thai", Category = "Thai", Ingredients = "Rice noodles
Shrimp or tofu
Eggs
Bean sprouts
Green onions
Peanuts
Lime
Fish sauce
Tamarind paste
Sugar", Steps = "1. Soak rice noodles in warm water 30 min
2. Make sauce: tamarind, fish sauce, sugar
3. Stir-fry protein until cooked
4. Push aside, scramble eggs
5. Add drained noodles and sauce
6. Toss with bean sprouts and peanuts
7. Serve with lime wedges", AverageRating = 4.6, RatingCount = 15 },
        new Recipe { Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate
Butter
Eggs
Sugar
Flour
Vanilla extract", Steps = "1. Melt chocolate and butter together
2. Whisk eggs and sugar until fluffy
3. Fold chocolate mixture into eggs
4. Add flour and vanilla, fold gently
5. Pour into greased ramekins
6. Bake at 425°F for 12-14 minutes
7. Invert onto plate, serve immediately", AverageRating = 4.9, RatingCount = 31 },
        new Recipe { Id = 6, Title = "Caesar Salad", Category = "Salads", Ingredients = "Romaine lettuce
Parmesan cheese
Croutons
Caesar dressing
Lemon juice
Garlic
Anchovy paste
Olive oil", Steps = "1. Wash and chop romaine lettuce
2. Make dressing: blend garlic, anchovy, lemon, oil
3. Toss lettuce with dressing
4. Top with shaved parmesan and croutons
5. Serve immediately", AverageRating = 4.0, RatingCount = 6 },
    };

    public static IReadOnlyList<Recipe> GetAll() => _recipes.AsReadOnly();

    public static IEnumerable<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c);

    public static IEnumerable<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase));

    public static Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public static void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is null) return;
        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
    }

    public static void Add(RecipeSubmission submission)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        });
    }
}

@rendermode InteractiveServer

<div class="star-rating">
    <span class="rating-label">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _selectedRating ? "filled" : "") @(star <= _hoverRating ? "hover" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => _hoverRating = star"
              @onmouseout="() => _hoverRating = 0">
            &#9733;
        </span>
    }
    @if (_submitted)
    {
        <span class="rating-thanks">Thanks! You rated @_selectedRating star@(_selectedRating != 1 ? "s" : "").</span>
    }
</div>

<style>
    .star-rating {
        display: flex;
        align-items: center;
        gap: 0.25rem;
        margin: 1rem 0;
    }
    .rating-label {
        margin-right: 0.5rem;
        font-weight: 500;
    }
    .star {
        font-size: 1.8rem;
        cursor: pointer;
        color: #ccc;
        transition: color 0.15s;
    }
    .star.filled { color: #f5a623; }
    .star.hover { color: #ffcc00; }
    .rating-thanks {
        margin-left: 0.75rem;
        color: #2e7d32;
        font-weight: 500;
    }
</style>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int _selectedRating;
    private int _hoverRating;
    private bool _submitted;

    private void Rate(int stars)
    {
        _selectedRating = stars;
        _submitted = true;
        RecipeCommunity.Models.RecipeStore.AddRating(RecipeId, stars);
    }
}

