toolArgs.file_text:
@page "/recipe/{Id:int}"
@using RecipeCommunity.Models
@using RecipeCommunity.Components.Shared

<PageTitle>@(recipe?.Title ?? "Recipe") - Recipe Community</PageTitle>

<nav aria-label="breadcrumb">
    <a href="/">Home</a> &rsaquo;
    @if (recipe is not null)
    {
        <a href="/category/@recipe.Category">@recipe.Category</a>
        <text> &rsaquo; </text>
        <strong>@recipe.Title</strong>
    }
</nav>

@if (recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
}
else
{
    <h1>@recipe.Title</h1>

    <div class="recipe-meta">
        <span class="badge">@recipe.Category</span>
        <span class="rating-display">
            @for (int i = 1; i <= 5; i++)
            {
                <span class="@(i <= Math.Round(recipe.AverageRating) ? "star-filled" : "star-empty")">&#9733;</span>
            }
            <span class="rating-text">@recipe.AverageRating avg (@recipe.RatingCount ratings)</span>
        </span>
    </div>

    <section class="recipe-section">
        <h2>Ingredients</h2>
        <ul>
            @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
            {
                <li>@ingredient</li>
            }
        </ul>
    </section>

    <section class="recipe-section">
        <h2>Steps</h2>
        @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <p>@step</p>
        }
    </section>

    <section class="recipe-section">
        <h2>Your Rating</h2>
        <StarRating RecipeId="@recipe.Id" />
    </section>
}

<style>
    nav { margin-bottom: 1.5rem; color: #666; }
    nav a { color: #1a73e8; text-decoration: none; }
    .recipe-meta { margin-bottom: 1.5rem; display: flex; align-items: center; gap: 1rem; }
    .badge {
        display: inline-block;
        padding: 0.2rem 0.6rem;
        background: #e8f5e9;
        border-radius: 4px;
        font-size: 0.85rem;
        color: #2e7d32;
    }
    .star-filled { color: #f5a623; }
    .star-empty { color: #ccc; }
    .rating-text { font-size: 0.85rem; color: #666; }
    .recipe-section { margin-bottom: 2rem; }
    .recipe-section h2 { border-bottom: 1px solid #eee; padding-bottom: 0.5rem; }
    .recipe-section ul { line-height: 1.8; }
    .recipe-section p { line-height: 1.6; }
</style>

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeStore.GetById(Id);
    }
}

